export type Objective = 1 | 2 | 3 | 4;
export type Points = 1 | 2 | 3 | 5 | 8;

export type QuizQuestion = {
  /** Short story card title (48 chars max). Falls back to the prompt's first sentence. */
  title?: string;
  /** Per-question user story ("As the ..., we need ..., so that ..."). Falls back to a team-level sentence. */
  story?: string;
  prompt: string;
  code?: string;
  /**
   * Expected trace mat values for the key cells (lines that assign a variable), keyed "<line>:<variable>"
   * with 1-based line numbers as shown on the mat. Generated by scripts/gen-trace-keys.py. Server only:
   * never part of the public mission.
   */
  traceKey?: Record<string, string>;
  options: string[];
  answer: string;
  explanation: string;
  /** 1 trace loop + if, 2 fix boundary error, 3 explain why, 4 Agile */
  objective: Objective;
  /** Suggested story points (teams re-estimate in planning). */
  points: Points;
};

export type ExitTicket = { prompt: string; code?: string };

export type SprintMission = {
  id: string;
  title: string;
  topic: string;
  topicKey: string;
  topicIcon: string;
  topicColor: string;
  description: string;
  xpReward: number;
  groupA: {
    role: string;
    challenge: string;
    questions: QuizQuestion[];
  };
  groupB: {
    role: string;
    challenge: string;
    questions: QuizQuestion[];
  };
  exitTicket: ExitTicket;
  handoffMessage: string;
  successMessage: string;
};
